const I={
 leaf:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M20 4c-7 0-13 3-13 9 0 3 2 5 5 5 6 0 8-7 8-14Z"/><path d="M4 20c3-6 7-9 13-12"/></svg>',
 grid:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/></svg>',
 device:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="5" y="3" width="14" height="18" rx="3"/><path d="M9 7h6M9 11h6M12 16v1"/></svg>',
 chart:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M4 19V5M4 19h16M7 15l4-5 3 3 5-7"/></svg>',
 history:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M3 12a9 9 0 1 0 3-6.7L3 8"/><path d="M3 3v5h5M12 7v5l3 2"/></svg>',
 bell:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg>',
 report:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M6 2h9l4 4v16H6zM14 2v5h5M9 12h6M9 16h6"/></svg>',
 user:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="12" cy="8" r="4"/><path d="M4 21c.8-4 3.5-6 8-6s7.2 2 8 6"/></svg>',
 settings:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="12" cy="12" r="3"/><path d="M19 12a7 7 0 0 0-.1-1l2-1.6-2-3.4-2.5 1A7 7 0 0 0 15 6l-.4-2.7h-4L10 6a7 7 0 0 0-1.4.8l-2.5-1-2 3.4L6 11a7 7 0 0 0 0 2l-2 1.6 2 3.4 2.5-1A7 7 0 0 0 10 18l.4 2.7h4L15 18a7 7 0 0 0 1.4-.8l2.5 1 2-3.4-2-1.6c.1-.4.1-.7.1-1.2Z"/></svg>',
 search:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/></svg>',
 plus:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 5v14M5 12h14"/></svg>',
 refresh:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M20 7v5h-5M4 17v-5h5"/><path d="M6 9a7 7 0 0 1 12-2l2 5M18 15a7 7 0 0 1-12 2l-2-5"/></svg>',
 download:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M12 3v12m-4-4 4 4 4-4M4 20h16"/></svg>',
 menu:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 7h16M4 12h16M4 17h16"/></svg>'
};
const nav=[['dashboard','Overview','grid'],['devices','Devices','device'],['analytics','Sensor Analytics','chart'],['history','Historical Data','history'],['alerts','Alerts','bell'],['reports','Reports / Export','report'],['profile','User Profile','user'],['settings','Settings','settings']];
const devices=[
 ['Greenhouse Node 01','AGR-ESP32-001','Greenhouse A','Enviro Node','Online','12 sec ago','92%',0],
 ['North Field Station','AGR-LORA-014','North Field','Field Station','Online','41 sec ago','78%',1],
 ['Reservoir Monitor','WTR-MQTT-003','Reservoir B','Water Node','Warning','2 min ago','34%',2],
 ['Weather Mast 02','ENV-SDI12-008','West Ridge','Weather Station','Online','23 sec ago','86%',0],
 ['Irrigation Valve 07','CTL-RS485-027','Sector 7','Control Node','Offline','38 min ago','—',1],
 ['Soil Probe Cluster','AGR-RS485-019','South Field','Soil Array','Online','1 min ago','65%',0]
];
const sensors=[['Air temperature','29.4','°C','Greenhouse Node 01','Normal'],['Relative humidity','76.2','%','Greenhouse Node 01','Normal'],['Soil moisture','42.8','%','North Field Station','Normal'],['Rainfall','2.4','mm','Weather Mast 02','Recent'],['Wind speed','12.6','km/h','Weather Mast 02','Normal'],['Battery voltage','3.82','V','Reservoir Monitor','Low']];
let route=location.hash.slice(1)||'dashboard';
const app=document.querySelector('#app');
const icon=(n)=>`<span class="icon">${I[n]||I.grid}</span>`;
const status=(s)=>`<span class="status ${/offline|critical|low/i.test(s)?'danger':/warning|recent|ack/i.test(s)?'warn':''}">${s}</span>`;
const spark=(offset=0)=>`<svg class="spark" viewBox="0 0 180 42" preserveAspectRatio="none"><polyline points="0,${28-offset} 20,24 40,29 60,17 80,21 100,12 120,19 140,9 160,14 180,7"/></svg>`;
function shell(content,title){return `<div class="overlay" onclick="toggleMenu()"></div><div class="shell"><aside class="sidebar"><div class="brand"><div class="brandmark">${I.leaf}</div><span>Verdant IoT</span></div><div class="workspace"><div><small>WORKSPACE</small><b>AgriOps Central</b></div><span>⌄</span></div><div class="nav-section">Monitor</div><nav class="nav">${nav.slice(0,6).map(n=>`<button class="${route===n[0]?'active':''}" onclick="go('${n[0]}')">${I[n[2]]}<span>${n[1]}</span></button>`).join('')}<div class="nav-section">Account</div>${nav.slice(6).map(n=>`<button class="${route===n[0]?'active':''}" onclick="go('${n[0]}')">${I[n[2]]}<span>${n[1]}</span></button>`).join('')}</nav><div class="profile-mini"><div class="avatar">AM</div><div><strong>Alex Morgan</strong><span>System Administrator</span></div></div></aside><main class="main"><header class="topbar"><div class="crumb"><button class="icon-btn menu-toggle" onclick="toggleMenu()">${I.menu}</button><span>AgriOps Central</span><span>/</span><b>${title}</b></div><div class="top-actions"><div class="search">${I.search}<input aria-label="Global device search" placeholder="Search devices, sensors…" onkeydown="if(event.key==='Enter')showToast('Search results updated')"></div><span class="live-pill"><i class="live-dot"></i> Live connection</span><button class="icon-btn" aria-label="Notifications" onclick="go('alerts')">${I.bell}<i class="dot"></i></button><div class="avatar">AM</div></div></header><section class="content">${content}</section></main></div>`}
function head(title,desc,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`}
function pageDashboard(){let k=[['48','Total devices','device','+6 this month'],['42','Online devices','grid','87.5% connected'],['4','Offline devices','device','Needs review','danger'],['2','Needs attention','bell','2 unresolved','warn'],['126','Active sensors','chart','98.7% reporting','blue'],['98.7%','Data availability','history','Last 30 days','blue']];return shell(`${head('Operations overview','System health and sensor activity across AgriOps Central.',`<button class="btn" onclick="refreshData()">${I.refresh} Refresh</button><select class="field"><option>Auto · 30 sec</option><option>1 min</option><option>Off</option></select>`)}<div class="kpis grid">${k.map(x=>`<div class="card kpi"><div class="kpi-top"><div class="kpi-icon ${x[4]||''}">${I[x[2]]}</div><span class="trend">${x[3]}</span></div><div class="kpi-value tabular">${x[0]}</div><div class="kpi-label">${x[1]}</div></div>`).join('')}</div><div class="grid two-col"><div class="card panel"><div class="panel-head"><div><h2>System health</h2><p>Live connectivity and ingestion status</p></div>${status('Operational')}</div><div class="health"><div class="donut"><div class="donut-label"><b>87.5%</b><span>connected</span></div></div><div><div class="health-row"><span>Devices online</span><b>42 / 48</b></div><div class="health-row"><span>Data ingestion</span>${status('Healthy')}</div><div class="health-row"><span>Communication failures</span><b style="color:#ef4444">4</b></div><div class="health-row"><span>Last successful sync</span><b>8 sec ago</b></div></div></div></div><div class="card panel"><div class="panel-head"><div><h2>Recent activity</h2><p>Events requiring context</p></div><button class="btn" onclick="go('alerts')">View all</button></div><div class="timeline"><div class="event"><b>Irrigation Valve 07 went offline</b><p>Sector 7 · 38 minutes ago</p></div><div class="event"><b>Reservoir battery below 35%</b><p>Reservoir B · 1 hour ago</p></div><div class="event"><b>Connection restored</b><p>Weather Mast 02 · 2 hours ago</p></div><div class="event"><b>Configuration updated</b><p>Greenhouse Node 01 · 4 hours ago</p></div></div></div></div><div class="panel-head"><div><h2>Sensor readings</h2><p>Illustrative prototype data · updated 8 seconds ago</p></div></div><div class="grid sensor-grid">${sensors.map((s,i)=>`<div class="card sensor"><div class="sensor-head"><h3>${s[0]}</h3>${status(s[4])}</div><div class="reading tabular">${s[1]} <small>${s[2]}</small></div>${spark(i%2)}<div class="sensor-foot"><span>${s[3]}</span><span>${i+8} sec ago</span></div></div>`).join('')}</div>${chartPanel()}${deviceTable(devices.slice(0,5),'Device status')}`,'Overview')}
function chartPanel(){return `<div class="card panel" style="margin-bottom:18px"><div class="panel-head"><div><h2>Environmental sensor trend</h2><p>Air temperature · Greenhouse Node 01 · Last 24 hours</p></div><div class="actions"><select class="field"><option>Air temperature</option><option>Soil temperature</option></select><select class="field"><option>24 hours</option><option>7 days</option><option>30 days</option></select></div></div><div class="legend"><span><i style="background:#10b981"></i>Current period</span><span><i style="background:#3b82f6"></i>Previous period</span></div><div class="chart"><svg viewBox="0 0 800 270" preserveAspectRatio="none"><defs><linearGradient id="area" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#10b981" stop-opacity=".18"/><stop offset="1" stop-color="#10b981" stop-opacity="0"/></linearGradient></defs><path class="area" d="M0 205 C70 198 90 156 145 166 S220 110 280 132 S370 82 425 98 S510 60 570 78 S670 38 800 58 L800 270 L0 270Z"/><path class="line1" d="M0 205 C70 198 90 156 145 166 S220 110 280 132 S370 82 425 98 S510 60 570 78 S670 38 800 58"/><path class="line2" d="M0 220 C80 210 100 180 160 190 S250 140 310 156 S390 105 460 128 S560 89 630 103 S720 72 800 88"/></svg><span class="axis-label" style="left:-37px;top:-5px">32°C</span><span class="axis-label" style="left:-37px;bottom:-5px">24°C</span><span class="axis-label" style="left:0;bottom:-22px">00:00</span><span class="axis-label" style="left:48%;bottom:-22px">12:00</span><span class="axis-label" style="right:0;bottom:-22px">Now</span></div></div>`}
function deviceTable(rows,title='All devices'){return `<div class="card"><div class="panel" style="padding-bottom:8px"><div class="panel-head"><div><h2>${title}</h2><p>${rows.length} visible devices · prototype dataset</p></div><button class="btn" onclick="exportData()">${I.download} Export</button></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Device</th><th>Location</th><th>Type</th><th>Status</th><th>Last seen</th><th>Battery</th><th>Alerts</th><th></th></tr></thead><tbody>${rows.map(d=>`<tr onclick="go('device-detail')"><td><div class="device-name">${d[0]}</div><div class="device-id">${d[1]}</div></td><td>${d[2]}</td><td>${d[3]}</td><td>${status(d[4])}</td><td>${d[5]}</td><td><div>${d[6]}</div><div class="battery"><span style="width:${d[6]}"></span></div></td><td>${d[7]}</td><td><button class="btn">View</button></td></tr>`).join('')}</tbody></table></div><div class="pagination"><span>Showing 1–${rows.length} of 48</span><div><button>‹</button><button class="active">1</button><button>2</button><button>›</button></div></div></div>`}
function pageDevices(){return shell(`${head('Devices','Manage registered gateways, field nodes, and sensor stations.',`<button class="btn">${I.download} Import</button><button class="btn primary" onclick="openModal('Add device','Register hardware with a device identifier and communication protocol.')">${I.plus} Add device</button>`)}<div class="toolbar"><div class="search" style="display:block">${I.search}<input placeholder="Search name or device ID"></div><select class="field"><option>All statuses</option><option>Online</option><option>Offline</option><option>Warning</option></select><select class="field"><option>All locations</option><option>Greenhouse A</option><option>North Field</option></select><select class="field"><option>All device types</option></select><div class="spacer"></div><button class="btn">Table</button><button class="btn">Grid</button></div>${deviceTable(devices)}`,'Devices')}
function pageDeviceDetail(){return shell(`${head('Device detail','Inspect live health, sensor channels, telemetry, and configuration.',`<button class="btn">Edit device</button><button class="btn">•••</button>`)}<div class="card detail-hero"><div class="detail-title"><div class="device-icon">${I.device}</div><div><div style="display:flex;gap:8px;align-items:center"><h2 style="margin:0">Greenhouse Node 01</h2>${status('Online')}</div><p class="muted" style="margin:5px 0 0">AGR-ESP32-001 · Greenhouse A · MQTT · last seen 12 sec ago</p></div></div><div class="actions"><span class="live-pill"><i class="live-dot"></i> Receiving telemetry</span></div></div><div class="tabs"><button class="active">Overview</button><button>Telemetry</button><button>Events</button><button>Settings</button></div><div class="stat-row"><div class="card stat"><span class="eyebrow">Signal strength</span><b>−67 dBm</b><span class="muted">Good</span></div><div class="card stat"><span class="eyebrow">Battery</span><b>3.96 V</b><span class="muted">92%</span></div><div class="card stat"><span class="eyebrow">Firmware</span><b>v2.8.4</b><span class="muted">Up to date</span></div><div class="card stat"><span class="eyebrow">Uptime</span><b>18d 7h</b><span class="muted">No restart</span></div><div class="card stat"><span class="eyebrow">Interval</span><b>30 sec</b><span class="muted">Configured</span></div></div><div class="grid two-col"><div>${chartPanel()}</div><div class="card panel"><div class="panel-head"><div><h2>Device health</h2><p>Latest reported diagnostics</p></div>${status('Healthy')}</div><div class="health-row"><span>Hardware model</span><b>ESP32-S3 Field</b></div><div class="health-row"><span>Protocol</span><b>MQTT / TLS</b></div><div class="health-row"><span>Last telemetry</span><b>12 sec ago</b></div><div class="health-row"><span>Reconnects (24h)</span><b>1</b></div><div class="health-row"><span>Transmission quality</span><b>99.4%</b></div><div class="health-row"><span>Gateway</span><b>GW-GHA-01</b></div></div></div><div class="card"><div class="panel"><div class="panel-head"><div><h2>Sensor channels</h2><p>4 active channels associated with this device</p></div></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Sensor</th><th>Identifier</th><th>Current</th><th>Thresholds</th><th>Quality</th><th>Last reading</th><th></th></tr></thead><tbody>${[['Air temperature','TMP-01','29.4 °C','18–34 °C'],['Relative humidity','HUM-01','76.2%','40–85%'],['Soil temperature','STP-02','25.8 °C','15–32 °C'],['Light intensity','LUX-01','34,820 lx','—']].map(s=>`<tr><td class="device-name">${s[0]}</td><td>${s[1]}</td><td><b>${s[2]}</b></td><td>${s[3]}</td><td>${status('Valid')}</td><td>12 sec ago</td><td><button class="btn" onclick="go('analytics')">Analytics</button></td></tr>`).join('')}</tbody></table></div></div>`,'Devices / Greenhouse Node 01')}
function pageAnalytics(){let stats=[['Latest','29.4 °C'],['Minimum','24.8 °C'],['Maximum','31.6 °C'],['Average','28.1 °C'],['Valid data','99.2%']];return shell(`${head('Sensor analytics','Explore patterns, thresholds, and data quality across compatible measurements.',`<button class="btn" onclick="exportData()">${I.download} Export data</button>`)}<div class="card panel" style="margin-bottom:16px"><div class="toolbar" style="margin:0"><select class="field"><option>Greenhouse Node 01</option></select><select class="field"><option>Air temperature</option></select><select class="field"><option>Greenhouse A</option></select><select class="field"><option>Last 7 days</option></select><select class="field"><option>Hourly</option></select><div class="spacer"></div><button class="btn">Reset</button><button class="btn primary" onclick="showToast('Filters applied')">Apply filters</button></div></div><div class="stat-row">${stats.map(s=>`<div class="card stat"><span class="eyebrow">${s[0]}</span><b>${s[1]}</b><span class="muted">Oct 11–18, hourly</span></div>`).join('')}</div>${chartPanel()}<div class="grid two-col"><div class="card panel"><div class="panel-head"><div><h2>Daily distribution</h2><p>Hourly samples grouped by temperature band</p></div></div><div style="height:190px;display:flex;align-items:end;gap:14px;padding:20px 20px 0;border-bottom:1px solid var(--border)">${[22,34,58,92,140,175,123,70].map((h,i)=>`<div style="flex:1;height:${h}px;background:${i===5?'#047857':'#a7f3d0'};border-radius:5px 5px 0 0" title="${22+i*2}°C"></div>`).join('')}</div></div><div class="card panel"><div class="panel-head"><div><h2>Data quality</h2><p>Sample validity over selected period</p></div>${status('Excellent')}</div><div class="health-row"><span>Valid samples</span><b>1,000</b></div><div class="health-row"><span>Missing samples</span><b>6</b></div><div class="health-row"><span>Outliers</span><b>2</b></div><div class="health-row"><span>Threshold violations</span><b>4</b></div><div class="health-row"><span>Standard deviation</span><b>1.83 °C</b></div></div></div>`,'Sensor Analytics')}
function pageHistory(){let rows=Array.from({length:8},(_,i)=>['Oct 18, 2026 · 10:'+(42-i*3).toString().padStart(2,'0')+':00','AGR-ESP32-001','Greenhouse Node 01',i%2?'Relative humidity':'Air temperature',i%2?(75.5+i*.2).toFixed(1)+'%':(28.7+i*.1).toFixed(1)+' °C','Valid','Greenhouse A']);return shell(`${head('Historical data','Search, filter, and export raw sensor records.',`<button class="btn" onclick="exportData()">${I.download} Export CSV</button>`)}<div class="card panel" style="margin-bottom:16px"><div class="toolbar" style="margin:0"><input class="field" placeholder="Search records…"><select class="field"><option>All devices</option></select><select class="field"><option>All sensors</option></select><input class="field" value="Oct 11 – Oct 18, 2026"><button class="btn primary">Apply</button></div></div><div class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>Timestamp</th><th>Device ID</th><th>Device name</th><th>Sensor</th><th>Value</th><th>Quality</th><th>Location</th></tr></thead><tbody>${rows.map(r=>`<tr>${r.map((v,i)=>`<td class="${i===4?'tabular':''}">${i===5?status(v):v}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="pagination"><span>Showing 1–8 of 184,206 records · server paginated</span><div><button>‹</button><button class="active">1</button><button>2</button><button>3</button><button>›</button></div></div></div>`,'Historical Data')}
function pageAlerts(){let a=[['Critical','Device offline','Irrigation Valve 07','CTL-RS485-027','No telemetry for 38 min','Unacknowledged'],['Warning','Low battery','Reservoir Monitor','WTR-MQTT-003','34% · threshold 35%','Acknowledged'],['Warning','High humidity','Greenhouse Node 01','AGR-ESP32-001','88.4% · threshold 85%','Unacknowledged'],['Info','Communication restored','Weather Mast 02','ENV-SDI12-008','Online after 4 min','Resolved']];return shell(`${head('Alerts & notifications','Triage operational events and track resolution status.',`<button class="btn">Notification rules</button>`)}<div class="toolbar"><div class="search" style="display:block">${I.search}<input placeholder="Search alerts"></div><select class="field"><option>All severities</option><option>Critical</option><option>Warning</option></select><select class="field"><option>Open alerts</option><option>Acknowledged</option><option>Resolved</option></select></div><div class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>Severity</th><th>Alert</th><th>Device</th><th>Current condition</th><th>Triggered</th><th>Status</th><th></th></tr></thead><tbody>${a.map((x,i)=>`<tr><td>${status(x[0])}</td><td class="device-name">${x[1]}</td><td><div>${x[2]}</div><div class="device-id">${x[3]}</div></td><td>${x[4]}</td><td>${i+1}h ago</td><td>${status(x[5])}</td><td><button class="btn" onclick="showToast('${x[5]==='Resolved'?'Alert history opened':'Alert acknowledged'}')">${x[5]==='Resolved'?'History':'Acknowledge'}</button></td></tr>`).join('')}</tbody></table></div></div>`,'Alerts')}
function pageReports(){return shell(`${head('Reports & export','Build operational reports from verified sensor and device data.',`<button class="btn primary" onclick="openModal('Create report','Choose a template, reporting period, and delivery format.')">${I.plus} Create report</button>`)}<div class="grid sensor-grid">${[['Weekly operations summary','Devices, uptime, alert volume','PDF · Weekly'],['Environmental trends','Temperature, humidity, rainfall','PDF · Monthly'],['Device inventory','Hardware, firmware, connectivity','CSV · On demand']].map((x,i)=>`<div class="card panel"><div class="kpi-icon ${i===1?'blue':''}">${I.report}</div><h2 style="font-size:15px;margin:16px 0 7px">${x[0]}</h2><p class="muted" style="min-height:32px">${x[1]}</p><div class="health-row"><span>Format / schedule</span><b>${x[2]}</b></div><div class="actions" style="margin-top:14px"><button class="btn" onclick="showToast('Report preview opened')">Preview</button><button class="btn" onclick="exportData()">Download</button></div></div>`).join('')}</div><div class="card empty"><div class="device-icon">${I.report}</div><h3>Scheduled delivery is ready to configure</h3><p>Create a report and choose recipients to automate delivery.</p><button class="btn primary" onclick="openModal('Schedule delivery','Select a report, cadence, and approved recipients.')">Set up schedule</button></div>`,'Reports / Export')}
function pageProfile(){return shell(`${head('User profile','Manage your identity, security, and monitoring preferences.',`<button class="btn primary" onclick="showToast('Profile changes saved')">Save changes</button>`)}<div class="settings-layout"><div class="card settings-nav"><button class="active">Personal information</button><button>Security</button><button>Preferences</button><button>Account information</button></div><div><div class="card setting-section"><div style="display:flex;gap:15px;align-items:center;margin-bottom:20px"><div class="avatar" style="width:56px;height:56px">AM</div><div><h2>Alex Morgan</h2><p style="margin:2px 0">System Administrator · AgriOps Central</p></div></div><div class="form-grid"><div class="form-group"><label>Full name</label><input value="Alex Morgan"></div><div class="form-group"><label>Email address</label><input value="alex@agriops.example"></div><div class="form-group"><label>Job title</label><input value="IoT Systems Administrator"></div><div class="form-group"><label>Organization</label><input value="AgriOps Central" disabled></div></div></div><div class="card setting-section"><h2>Security</h2><p>Protect your account and monitor access.</p><div class="pref-row"><div><b>Two-factor authentication</b><span>Authentication app enabled</span></div>${status('Enabled')}</div><div class="pref-row"><div><b>Active sessions</b><span>2 trusted sessions</span></div><button class="btn">Review</button></div><div class="pref-row"><div><b>Password</b><span>Last changed 42 days ago</span></div><button class="btn">Change</button></div></div></div></div>`,'User Profile')}
function pageSettings(){return shell(`${head('Settings','Configure workspace defaults, policies, integrations, and access.',`<button class="btn primary" onclick="showToast('Workspace settings saved')">Save changes</button>`)}<div class="settings-layout"><div class="card settings-nav"><button class="active">Workspace</button><button>Device defaults</button><button>Alert thresholds</button><button>Data retention</button><button>Notifications</button><button>API & integrations</button><button>Roles</button><button>Audit log</button></div><div><div class="card setting-section"><h2>Workspace settings</h2><p>General identity and regional defaults for AgriOps Central.</p><div class="form-grid"><div class="form-group"><label>Workspace name</label><input value="AgriOps Central"></div><div class="form-group"><label>Default timezone</label><select class="field" style="width:100%"><option>Asia/Jakarta (UTC+7)</option></select></div><div class="form-group"><label>Date format</label><select class="field" style="width:100%"><option>DD MMM YYYY</option></select></div><div class="form-group"><label>Temperature unit</label><select class="field" style="width:100%"><option>Celsius (°C)</option><option>Fahrenheit (°F)</option></select></div></div></div><div class="card setting-section"><h2>Operational defaults</h2><p>Applied to newly registered devices unless overridden.</p><div class="pref-row"><div><b>Offline timeout</b><span>Classify after 3 missed reporting intervals</span></div><select class="field"><option>3 intervals</option></select></div><div class="pref-row"><div><b>Data freshness indicator</b><span>Warn when telemetry is older than expected</span></div><button class="toggle" aria-label="Toggle freshness warnings"></button></div><div class="pref-row"><div><b>Default data retention</b><span>Raw telemetry storage period</span></div><select class="field"><option>24 months</option></select></div></div><div class="card setting-section"><h2>API credentials</h2><p>Secrets are masked and cannot be retrieved after creation.</p><div class="pref-row"><div><b>Production ingestion key</b><span>•••• •••• •••• B7K2 · created Aug 12, 2026</span></div><button class="btn" onclick="openModal('Rotate API key','The current key will stop working after the 24-hour grace period.')">Rotate key</button></div></div></div></div>`,'Settings')}
function authPage(signup=false){return `<div class="auth"><section class="auth-visual"><div class="brand" style="padding:0"><div class="brandmark">${I.leaf}</div><span>Verdant IoT</span></div><div class="auth-copy"><span class="live-pill"><i class="live-dot"></i> Operational intelligence</span><h1>Every signal.<br>One clear view.</h1><p>Monitor remote assets, investigate sensor patterns, and respond to field conditions from a secure operations workspace.</p><div class="auth-metrics"><div class="auth-metric"><b>48</b><span>connected devices</span></div><div class="auth-metric"><b>98.7%</b><span>data availability</span></div><div class="auth-metric"><b>126</b><span>sensor channels</span></div></div></div><small style="color:#60736c">Illustrative prototype data · no live hardware connected</small></section><section class="auth-form-wrap"><form class="auth-form" onsubmit="event.preventDefault(); login(this)"><h2>${signup?'Create your account':'Welcome back'}</h2><p>${signup?'Set up your secure monitoring workspace.':'Sign in to continue to AgriOps Central.'}</p>${signup?`<div class="form-group"><label>Full name</label><input required placeholder="Alex Morgan"></div>`:''}<div class="form-group"><label>Work email</label><input required type="email" value="${signup?'':'alex@agriops.example'}" placeholder="you@company.com"></div>${signup?`<div class="form-group"><label>Organization <span class="muted">(optional)</span></label><input placeholder="Company name"></div>`:''}<div class="form-group"><label>Password</label><div class="password-wrap"><input id="pw" required type="password" value="${signup?'':'verdant-demo'}" minlength="8"><button type="button" onclick="togglePassword()">Show</button></div>${signup?`<div class="strength"><i></i><i></i><i></i><i></i></div><small class="muted">Strong · 8+ characters with a number</small>`:''}</div>${signup?`<div class="form-group"><label>Confirm password</label><input required type="password" minlength="8"></div>`:`<div class="check-row"><label><input type="checkbox" checked> Remember me</label><a class="link" href="#">Forgot password?</a></div>`}${signup?`<div class="check-row" style="justify-content:flex-start;gap:8px"><input type="checkbox" required><span>I agree to the <a class="link">Terms</a> and <a class="link">Privacy Policy</a></span></div>`:''}<button class="btn primary" type="submit">${signup?'Create account':'Sign in'}</button><div class="divider">or continue with</div><button class="btn" type="button" onclick="showToast('Google authentication requires a connected backend')">G&nbsp;&nbsp; Continue with Google</button><p style="text-align:center;font-size:12px;margin-top:20px">${signup?'Already have an account?':'New to Verdant IoT?'} <a class="link" href="#${signup?'login':'signup'}">${signup?'Sign in':'Create account'}</a></p></form></section></div>`}
function render(){route=location.hash.slice(1)||'dashboard';let pages={dashboard:pageDashboard,devices:pageDevices,'device-detail':pageDeviceDetail,analytics:pageAnalytics,history:pageHistory,alerts:pageAlerts,reports:pageReports,profile:pageProfile,settings:pageSettings,login:()=>authPage(false),signup:()=>authPage(true)};app.innerHTML=(pages[route]||pageDashboard)();scrollTo(0,0)}
function go(r){location.hash=r}
function toggleMenu(){document.querySelector('.sidebar')?.classList.toggle('open');document.querySelector('.overlay')?.classList.toggle('open')}
function showToast(msg){let t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2500)}
function refreshData(){showToast('Sensor data synchronized · just now')}
function exportData(){showToast('Export prepared with current filters')}
function togglePassword(){let p=document.querySelector('#pw');p.type=p.type==='password'?'text':'password';event.currentTarget.textContent=p.type==='password'?'Show':'Hide'}
function login(form){let b=form.querySelector('button[type=submit]');b.disabled=true;b.textContent='Please wait…';setTimeout(()=>{showToast(route==='signup'?'Account created · verify your email':'Signed in to prototype workspace');location.hash='dashboard';},700)}
function openModal(title,text){document.body.insertAdjacentHTML('beforeend',`<div class="modal" onclick="if(event.target===this)this.remove()"><div class="modal-card"><h2>${title}</h2><p>${text}</p><div class="form-group"><label>Name or identifier</label><input placeholder="Enter a value"></div><div class="actions"><button class="btn" onclick="this.closest('.modal').remove()">Cancel</button><button class="btn primary" onclick="showToast('Action saved');this.closest('.modal').remove()">Continue</button></div></div></div>`)}
window.addEventListener('hashchange',render);render();
